int main() {
    std::ifstream in("bphoto.in");std::ofstream out("bphoto.out");int n;in >> n;std::vector<long long> height(n),values;for(auto& x:height) in >> x;values=height;std::sort(values.begin(),values.end());
    std::vector<int> rank(n),left(n),right(n),tree(n+1,0);for(int i=0;i<n;++i) rank[i]=static_cast<int>(std::lower_bound(values.begin(),values.end(),height[i])-values.begin())+1;
    auto add=[&](int at){for(;at<=n;at+=at&-at) ++tree[at];};
    auto sum=[&](int at){int count=0;for(;at>0;at-=at&-at) count+=tree[at];return count;};
    for(int i=0;i<n;++i){left[i]=i-sum(rank[i]);add(rank[i]);}
    std::fill(tree.begin(),tree.end(),0);
    for(int i=n-1;i>=0;--i){right[i]=n-1-i-sum(rank[i]);add(rank[i]);}
    int answer=0;for(int i=0;i<n;++i) if(std::max(left[i],right[i])>2*std::min(left[i],right[i])) ++answer;
    out << answer << '\n';
}
