#include <vector>
int main() {
    std::ifstream in("hps.in");std::ofstream out("hps.out");int n,k;in >> n >> k;std::vector<int> opponent(n);
    for(auto& x:opponent){char c;in >> c;x=(c=='H'?0:c=='P'?1:2);}
    const int impossible=-1000000;
    std::vector<std::array<int,3>> old(k+1,{impossible,impossible,impossible}),next=old;
    for(int mine=0;mine<3;++mine) old[0][mine]=(((opponent[0]+1)%3==mine)?1:0);
    for(int game=1;game<n;++game) {
        int gesture=opponent[game];
        for(auto& row:next) row={impossible,impossible,impossible};
        for(int switches=0;switches<=k;++switches) for(int mine=0;mine<3;++mine) {
            int best=old[switches][mine];
            if(switches>0) for(int previous=0;previous<3;++previous) if(previous!=mine) best=std::max(best,old[switches-1][previous]);
            if(best!=impossible) next[switches][mine]=best+(((gesture+1)%3==mine)?1:0);
        }
        old.swap(next);
    }
    int answer=0;for(const auto& row:old) answer=std::max(answer,*std::max_element(row.begin(),row.end()));out << answer << '\n';
}
