#include <string>
#include <vector>
int main() {
    std::ifstream in("cownav.in");std::ofstream out("cownav.out");int n;in >> n;std::vector<std::string> board(n);for(auto& row:board) in >> row;
    const int poses=4*n*n,goal=n-1,finished=4*goal;
    const int dr[4]={-1,0,1,0},dc[4]={0,1,0,-1};
    std::vector<std::array<int,3>> transition(poses);
    for(int p=0;p<poses;++p) {
        int cell=p/4,d=p%4,r=cell/n,c=cell%n;
        if(cell==goal){transition[p]={finished,finished,finished};continue;}
        transition[p][1]=4*cell+(d+3)%4;transition[p][2]=4*cell+(d+1)%4;
        int rr=r+dr[d],cc=c+dc[d];transition[p][0]=p;
        if(rr>=0&&rr<n&&cc>=0&&cc<n&&board[rr][cc]=='E') {int to=rr*n+cc;transition[p][0]=(to==goal?finished:4*to+d);}
    }
    int up=4*((n-1)*n),right=up+1,start=up*poses+right,target=finished*poses+finished;
    std::vector<int> distance(poses*poses,-1),pending;pending.reserve(poses*poses);distance[start]=0;pending.push_back(start);
    for(std::size_t head=0;head<pending.size();++head) {
        int state=pending[head];if(state==target){out << distance[state] << '\n';return 0;}
        int a=state/poses,b=state%poses;
        for(int command=0;command<3;++command) {int next=transition[a][command]*poses+transition[b][command];if(distance[next]==-1){distance[next]=distance[state]+1;pending.push_back(next);}}
    }
    out << -1 << '\n'; // Defensive only: the source path guarantee and absorbing goal imply a solution.
}
